/**
 * Vertice - Herramienta: Área de respeto
 * ------------------------------------------------------------------
 * Calcula el area de seguridad del logo a partir de una medida X
 * tomada del propio logo, de modo que quede justificada y sea
 * escalable: si el logo crece, el area crece con el.
 *
 *   - Si el logo tiene varias piezas, X sale de una de ellas.
 *   - Si es una pieza unica, X es una reduccion del propio logo, y se
 *     dibuja esa reduccion junto a la cota para que se vea de donde sale.
 */

if (typeof CG === "undefined") { var CG = {}; }

(function (CG) {

    var NOMBRE_CAPA = "AREA DE RESPETO";

    /**
     * Piezas independientes del logo. Un trazado compuesto cuenta como una
     * sola pieza: sus subtrazados son contraformas, no elementos sueltos.
     */
    function piezasDe(sel) {
        if (sel.length > 1) {
            var v = [];
            for (var i = 0; i < sel.length; i++) v.push(sel[i]);
            return v;
        }
        var it = sel[0];
        if (it.typename === "GroupItem") {
            var g = [];
            for (var j = 0; j < it.pageItems.length; j++) g.push(it.pageItems[j]);
            return g;
        }
        return [it];
    }

    function dimensiones(item) {
        var b = item.geometricBounds;
        return { ancho: b[2] - b[0], alto: b[1] - b[3] };
    }

    CG.areaRespeto = function (opcionesJSON) {
        try {
            var opt = eval("(" + opcionesJSON + ")");
            CG.idioma = (opt && opt._idioma) || "es";

            var ctx = CG.contexto();
            if (ctx.error) return '{"ok":false,"error":"' + CG.escapaJSON(ctx.error) + '"}';

            var doc = ctx.doc;
            var caja = ctx.bounds;
            var L = caja[0], T = caja[1], R = caja[2], B = caja[3];
            var anchoLogo = ctx.ancho, altoLogo = ctx.alto;

            var piezas = piezasDe(ctx.seleccion);

            // --- De donde sale X ---
            var X = 0, origen = "", pieza = null;
            var modo = opt.modo;

            if (modo === "auto") modo = (piezas.length >= 2) ? "pieza" : "fraccion";

            if (modo === "pieza" && piezas.length >= 2) {
                var mejor = null, mejorVal = null;
                for (var i = 0; i < piezas.length; i++) {
                    var d = dimensiones(piezas[i]);
                    var val = Math.max(d.ancho, d.alto);
                    if (val <= 0) continue;
                    if (mejorVal === null ||
                        (opt.piezaMayor ? val > mejorVal : val < mejorVal)) {
                        mejorVal = val; mejor = piezas[i];
                    }
                }
                if (!mejor) {
                    return '{"ok":false,"error":"No se pudo medir ninguna pieza del logo."}';
                }
                pieza = mejor;
                var dm = dimensiones(mejor);
                X = (opt.dimension === "ancho") ? dm.ancho
                  : (opt.dimension === "alto")  ? dm.alto
                  : Math.max(dm.ancho, dm.alto);
                origen = (opt.piezaMayor ? "pieza mayor" : "pieza menor") +
                         " del logo (" + X.toFixed(1) + " pt)";
            } else {
                modo = "fraccion";
                var div = opt.divisor > 0 ? opt.divisor : 4;
                X = altoLogo / div;
                origen = "alto del logo ÷ " + div;
            }

            if (X <= 0) return '{"ok":false,"error":"La medida X resultó nula."}';

            var k = opt.multiplo > 0 ? opt.multiplo : 1;
            var margen = X * k;

            // --- Capa y grupo ---
            var capa;
            try {
                capa = doc.layers.getByName(CG.N(NOMBRE_CAPA));
                capa.locked = false;
                capa.visible = true;
            } catch (e) {
                capa = doc.layers.add();
                capa.name = CG.N(NOMBRE_CAPA);
            }
            try { capa.zOrder(ZOrderMethod.BRINGTOFRONT); } catch (e) {}

            var nombreGrupo = "Respeto [" + Math.round(ctx.centroX) + ", " + Math.round(ctx.centroY) + "]";
            for (var gi = capa.groupItems.length - 1; gi >= 0; gi--) {
                if (capa.groupItems[gi].name === nombreGrupo) capa.groupItems[gi].remove();
            }
            var raiz = capa.groupItems.add();
            raiz.name = nombreGrupo;

            var rgb = CG.hexARgb(opt.color) || [89, 89, 89];
            var rgbX = CG.hexARgb(opt.colorX) || [20, 115, 230];
            var est = {
                color: CG.creaColor(doc, rgb[0], rgb[1], rgb[2]),
                grosor: ctx.diagonal * opt.pctGrosor / 100,
                punteado: opt.punteado,
                opacidad: opt.opacidad
            };
            var estX = {
                color: CG.creaColor(doc, rgbX[0], rgbX[1], rgbX[2]),
                grosor: ctx.diagonal * opt.pctGrosor / 100,
                punteado: false,
                opacidad: opt.opacidad
            };

            // --- Caja del logo ---
            if (opt.cajaLogo) {
                var gl = raiz.groupItems.add();
                gl.name = CG.N("Caja del logo");
                CG.dibujaLinea(gl, [L, T], [R, T], est);
                CG.dibujaLinea(gl, [R, T], [R, B], est);
                CG.dibujaLinea(gl, [R, B], [L, B], est);
                CG.dibujaLinea(gl, [L, B], [L, T], est);
            }

            // --- Límite del área de respeto ---
            var gL = raiz.groupItems.add();
            gL.name = CG.N("Limite del area");
            var eL = L - margen, eT = T + margen, eR = R + margen, eB = B - margen;
            CG.dibujaLinea(gL, [eL, eT], [eR, eT], estX);
            CG.dibujaLinea(gL, [eR, eT], [eR, eB], estX);
            CG.dibujaLinea(gL, [eR, eB], [eL, eB], estX);
            CG.dibujaLinea(gL, [eL, eB], [eL, eT], estX);

            // --- Cuadrados de X en los cuatro lados ---
            // Rellenan justo el hueco entre la caja del logo y el limite, que es
            // lo que hace evidente la medida de un vistazo.
            var gX = raiz.groupItems.add();
            gX.name = CG.N("Medida X");
            var cxLogo = (L + R) / 2, cyLogo = (T + B) / 2;

            function cuadro(x, y) {          // esquina superior izquierda
                var r = gX.pathItems.rectangle(y, x, margen, margen);
                r.filled = false;
                r.stroked = true;
                r.strokeColor = estX.color;
                r.strokeWidth = estX.grosor;
                r.strokeDashes = [];
                r.opacity = estX.opacidad;
                return r;
            }
            cuadro(cxLogo - margen / 2, eT);              // arriba
            cuadro(cxLogo - margen / 2, B);               // abajo
            cuadro(eL, cyLogo + margen / 2);              // izquierda
            cuadro(R,  cyLogo + margen / 2);              // derecha

            // --- Etiquetas ---
            var tamTexto = Math.max(4, ctx.diagonal * opt.pctTexto / 100);
            var etiqueta = (k === 1) ? "X" : (String(k) + "X");
            CG.dibujaTexto(gX, etiqueta, cxLogo, eT - margen / 2, tamTexto, estX.color);
            CG.dibujaTexto(gX, etiqueta, cxLogo, B - margen / 2, tamTexto, estX.color);
            CG.dibujaTexto(gX, etiqueta, eL + margen / 2, cyLogo, tamTexto, estX.color);
            CG.dibujaTexto(gX, etiqueta, R + margen / 2, cyLogo, tamTexto, estX.color);

            // --- Justificación de X ---
            // En modo fracción se coloca una reducción real del logo a la altura
            // de X: así se ve de dónde sale la medida y el criterio es replicable.
            var conMuestra = false;
            if (opt.mostrarOrigen) {
                var gO = raiz.groupItems.add();
                gO.name = CG.N("Origen de X");
                var yNota = eB - margen * 0.9;

                if (modo === "fraccion") {
                    try {
                        var copias = [];
                        for (var s = 0; s < ctx.seleccion.length; s++) {
                            copias.push(ctx.seleccion[s].duplicate(gO, ElementPlacement.PLACEATEND));
                        }
                        var cajaC = CG.cajaDe(copias);
                        var escala = X / (cajaC[1] - cajaC[3]) * 100;
                        for (var c = 0; c < copias.length; c++) {
                            copias[c].resize(escala, escala, true, true, true, true, escala,
                                             Transformation.TOPLEFT);
                        }
                        var cajaR = CG.cajaDe(copias);
                        var ddx = eL - cajaR[0];
                        var ddy = (yNota - margen * 0.15) - cajaR[1];
                        for (c = 0; c < copias.length; c++) copias[c].translate(ddx, ddy);
                        conMuestra = true;
                    } catch (eDup) { /* si no se puede duplicar, solo va la nota */ }
                }

                var nota = "X = " + origen;
                if (conMuestra) nota += "  ·  el logo reducido al " + (100 / opt.divisor).toFixed(1) + "%";
                nota += "   |   Área de respeto = " + etiqueta;
                var tf = CG.dibujaTexto(gO, nota, cxLogo, yNota - margen * 0.8,
                                        tamTexto * 0.85, estX.color);
                // La nota se alinea a la izquierda del área, no centrada.
                tf.position = [eL + (conMuestra ? X * 1.4 : 0), tf.position[1]];
            }

            if (opt.bloquear) capa.locked = true;
            app.redraw();

            return '{"ok":true,' +
                   '"X":' + X.toFixed(2) + ',' +
                   '"multiplo":' + k + ',' +
                   '"margen":' + margen.toFixed(2) + ',' +
                   '"modo":"' + CG.escapaJSON(modo) + '",' +
                   '"origen":"' + CG.escapaJSON(origen) + '",' +
                   '"piezas":' + piezas.length + '}';

        } catch (e) {
            return '{"ok":false,"error":"' +
                   CG.escapaJSON("Error interno: " + e + " (línea " + e.line + ")") + '"}';
        }
    };

})(CG);
